p = 61
counts = {0: 0, 1: 0, 2: 0, 61: 0}

for k in range(p):
    num_solutions = 0
    # Check solutions x in {0, 1, ..., 60}
    for x in range(p):
        if (x*x) % p == k:
            num_solutions += 1

    if num_solutions in counts:
        counts[num_solutions] += 1
    else:
        # Should not happen given the context, but good practice
        print(f"Unexpected number of solutions for k={k}: {num_solutions}")

print(f"Number of k values with 0 solutions: {counts[0]}")
print(f"Number of k values with 1 solution: {counts[1]}")
print(f"Number of k values with 2 solutions: {counts[2]}")
print(f"Number of k values with 61 solutions: {counts[61]}")
